/// Native replay implementations for midi bindings.
#[inline]
fn destack_midi_backend_list_replay(
    binding: &BindingCallContext,
    world: RuntimeWorld,
    out: *mut NativeSlice<MidiBackendDescriptor>,
) -> RuntimeResult<()> {
    binding.trace().run_binding_without_context(
        MIDI_BACKEND_LIST,
        binding.replay_payload_for(MIDI_BACKEND_LIST)?,
        || match world {
            RuntimeWorld::Host => unsafe {
                platform_native::destack_midi_backend_list(binding, out)
            },
            RuntimeWorld::Simulation => unsafe {
                platform_simulation_native::destack_midi_backend_list(binding, out)
            },
        },
        |result| {
            if let Ok(()) = result {
                let result_value: NativeSlice<MidiBackendDescriptor> = unsafe { out.read() };
                let mut result_recorded = Vec::new();
                for result_recorded_item in unsafe { result_value.as_slice()? }.iter().cloned() {
                    let result_recorded_item_recorded_backend = result_recorded_item.backend;
                    let result_recorded_item_recorded_name =
                        unsafe { result_recorded_item.name.as_str()? }.to_string();
                    let result_recorded_item_recorded_support = result_recorded_item.support;
                    let result_recorded_item_recorded_priority = result_recorded_item.priority;
                    let result_recorded_item_recorded_capability_flags =
                        result_recorded_item.capability_flags;
                    let result_recorded_item_recorded_supported_data_formats =
                        result_recorded_item.supported_data_formats;
                    let result_recorded_item_recorded_supported_protocols =
                        result_recorded_item.supported_protocols;
                    let result_recorded_item_recorded = MidibackenddescriptorReplayRecord {
                        backend: result_recorded_item_recorded_backend,
                        name: result_recorded_item_recorded_name,
                        support: result_recorded_item_recorded_support,
                        priority: result_recorded_item_recorded_priority,
                        capability_flags: result_recorded_item_recorded_capability_flags,
                        supported_data_formats:
                            result_recorded_item_recorded_supported_data_formats,
                        supported_protocols: result_recorded_item_recorded_supported_protocols,
                    };
                    result_recorded.push(result_recorded_item_recorded);
                }
                let payload = MidiBackendListReplayRecord {
                    result: Ok(result_recorded),
                };
                return Ok(Some(payload));
            }

            if let Err(error) = result {
                let payload = {
                    let result = Err(TraceError::from(error.as_ref()));
                    MidiBackendListReplayRecord { result }
                };
                return Ok(Some(payload));
            }

            Ok(None)
        },
        |payload| {
            // replay result
            match payload.result {
                Ok(value) => {
                    let mut value_native_values = Vec::new();
                    for value_native_item in value.iter().cloned() {
                        let value_native_decoded_backend = value_native_item.backend;
                        let value_native_decoded_name =
                            binding.store_string(value_native_item.name.as_str());
                        let value_native_decoded_support = value_native_item.support;
                        let value_native_decoded_priority = value_native_item.priority;
                        let value_native_decoded_capability_flags =
                            value_native_item.capability_flags;
                        let value_native_decoded_supported_data_formats =
                            value_native_item.supported_data_formats;
                        let value_native_decoded_supported_protocols =
                            value_native_item.supported_protocols;
                        let value_native_decoded = MidiBackendDescriptor {
                            backend: value_native_decoded_backend,
                            name: value_native_decoded_name,
                            support: value_native_decoded_support,
                            priority: value_native_decoded_priority,
                            capability_flags: value_native_decoded_capability_flags,
                            supported_data_formats: value_native_decoded_supported_data_formats,
                            supported_protocols: value_native_decoded_supported_protocols,
                        };
                        value_native_values.push(value_native_decoded);
                    }
                    let value_native = binding.store_slice(value_native_values);
                    unsafe { out.write(value_native) };
                    Ok(())
                }
                Err(error) => Err(Box::<RuntimeError>::from(error)),
            }
        },
    )
}

